public class Main {
    public static double celsiusToFahrenheit(double celsius) {
        return celsius * 9.0 / 5.0 + 32.0;
    }
    public static void main(String[] args) {
        double celsius = 25.0;
        System.out.printf("%.1f C = %.1f F%n", celsius, celsiusToFahrenheit(celsius));
    }
}
